<script setup lang="ts">
import {computed,nextTick,ref,useAttrs,watch,onUnmounted} from 'vue';
import {Popup as TPopup} from 'tdesign-vue-next';
import {calendarCells,civilDay,shiftMonth} from '../../domain/civil-calendar';
import {currentZone} from '../../domain/todos';
import {calendarDate} from '../../../runtime/dates.mjs';
import {useControl,useDisabled} from './control';
import SkButton from './SkButton.vue';import Icon from '../Icon.vue';
defineOptions({inheritAttrs:false});
const props=withDefaults(defineProps<{modelValue:string;dateOnly?:boolean;disabled?:boolean;placeholder?:string}>(),{modelValue:''});
const emit=defineEmits<{'update:modelValue':[value:string];change:[value:string]}>(),attrs=useAttrs(),disabled=useDisabled(props),{root}=useControl(attrs,'button');
const open=ref(false),month=ref(''),day=ref(''),hour=ref('09'),minute=ref('00'),error=ref(''),panel=ref<HTMLElement>();
const today=computed(()=>calendarDate(Date.now(),currentZone())),cells=computed(()=>calendarCells(month.value||today.value.slice(0,7)));
let focusFrame=0;
function focusVisible(attempts=8){cancelAnimationFrame(focusFrame);if(!open.value)return;focusFrame=requestAnimationFrame(()=>{if(!open.value)return;const element=panel.value,target=element?.querySelector<HTMLButtonElement>('[tabindex="0"]');if(element?.contains(document.activeElement))return;if(target?.getClientRects().length&&getComputedStyle(target).visibility==='visible'){target.focus();if(document.activeElement===target)return;}if(attempts>0)focusVisible(attempts-1);});}
onUnmounted(()=>cancelAnimationFrame(focusFrame));
const focusDay=computed(()=>day.value.startsWith(month.value)?day.value:month.value+'-01');
function attach(){return root.value?.closest('dialog')||document.body;}
watch(open,async visible=>{if(visible){if(disabled.value){open.value=false;return;}const [date,time='09:00']=props.modelValue.replace(' ','T').split('T');day.value=date||today.value;month.value=day.value.slice(0,7);[hour.value,minute.value]=time.split(':');error.value='';await nextTick();focusVisible();}else cancelAnimationFrame(focusFrame);});
watch(disabled,value=>{if(value)open.value=false;});
watch(panel,async element=>{if(!element)return;await nextTick();if(open.value)focusVisible();});
function triggerKey(event:KeyboardEvent){if(event.key==='Escape'&&open.value){event.preventDefault();event.stopPropagation();close();}}
function close(){open.value=false;void nextTick(()=>root.value?.querySelector<HTMLButtonElement>('button')?.focus());}
function commit(clear=false){if(!clear&&!props.dateOnly&&(!/^\d{1,2}$/.test(hour.value)||!/^\d{1,2}$/.test(minute.value)||Number(hour.value)>23||Number(minute.value)>59)){error.value='请输入0–23的小时和0–59的分钟。';return;}const value=clear?'':day.value+(props.dateOnly?'':`T${hour.value.padStart(2,'0')}:${minute.value.padStart(2,'0')}`);emit('update:modelValue',value);emit('change',value);close();}
function choose(value:string){day.value=value;month.value=value.slice(0,7);error.value='';}
async function key(event:KeyboardEvent){const target=event.target as HTMLElement;if(!target.dataset.day)return;const at=Date.parse(target.dataset.day+'T12:00Z'),weekday=(new Date(at).getUTCDay()+6)%7;const delta:Record<string,number>={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7,Home:-weekday,End:6-weekday};if(event.key in delta){event.preventDefault();choose(civilDay(at+delta[event.key]*86400000));}else if(['PageUp','PageDown'].includes(event.key)){event.preventDefault();month.value=shiftMonth(month.value,event.key==='PageUp'?-1:1);day.value=month.value+'-01';}else return;await nextTick();panel.value?.querySelector<HTMLButtonElement>(`[data-day="${day.value}"]`)?.focus();}
</script>
<template><div ref="root" class="sk-control sk-date" :class="attrs.class"><TPopup :visible="open" destroy-on-close trigger="click" placement="bottom-left" :attach="attach" overlay-class-name="sk-date-popup" :z-index="6000" :popper-options="{strategy:'fixed',modifiers:[{name:'preventOverflow',options:{boundary:'viewport',padding:10}}]}" @visible-change="open=$event"><button class="sk-date-trigger" type="button" :disabled="disabled" aria-haspopup="dialog" :aria-expanded="open" @keydown.down.prevent="open=true" @keydown="triggerKey"><span :class="{muted:!modelValue}">{{modelValue.replace('T',' ')||placeholder||(dateOnly?'选择日期':'选择日期与时间')}}</span><Icon :name="dateOnly?'today':'clock'"/></button><template #content><div ref="panel" class="sk-calendar" role="dialog" :aria-label="dateOnly?'选择日期':'选择日期与时间'" @keydown.esc.stop.prevent="close" @keydown="key"><header><button class="icon-button previous-month" type="button" aria-label="上个月" @click="month=shiftMonth(month,-1)"><Icon name="arrow"/></button><strong>{{Number(month.slice(0,4))}}年 {{Number(month.slice(5))}}月</strong><button class="icon-button" type="button" aria-label="下个月" @click="month=shiftMonth(month,1)"><Icon name="arrow"/></button></header><div class="sk-weekdays" aria-hidden="true"><span v-for="label in ['一','二','三','四','五','六','日']" :key="label">{{label}}</span></div><div class="sk-calendar-grid" role="grid" :aria-label="`${month}日历`"><div v-for="week in 6" :key="week" role="row"><button v-for="date in cells.slice((week-1)*7,week*7)" :key="date" :data-day="date" type="button" role="gridcell" :aria-selected="day===date" :aria-label="date" :tabindex="date===focusDay?0:-1" :class="{outside:!date.startsWith(month),today:date===today}" @click="choose(date)">{{Number(date.slice(-2))}}</button></div></div><div class="sk-calendar-shortcuts"><button class="text-button" type="button" @click="choose(today)">今天</button><span>已选 {{day}}</span></div><div v-if="!dateOnly" class="sk-calendar-time"><span>时间</span><label>小时<input v-model="hour" inputmode="numeric" maxlength="2" aria-label="小时"></label><span>:</span><label>分钟<input v-model="minute" inputmode="numeric" maxlength="2" aria-label="分钟"></label><small class="muted">24小时制</small></div><p v-if="error" class="sk-error" role="alert">{{error}}</p><footer><SkButton kind="quiet" @click="commit(true)">清空</SkButton><span/><SkButton kind="quiet" @click="close">取消</SkButton><SkButton kind="commit" @click="commit()">确定</SkButton></footer></div></template></TPopup></div></template>
